using System;using Phantom.Calibration;using Phantom.Kinematics;using Phantom.Mapping;using Phantom.Networking;using Phantom.Networking.Generated;
internal static class CoreSmoke
{
 static void Check(bool c,string m){if(!c)throw new Exception(m);}static byte[] Id(byte s){var b=new byte[16];for(var i=0;i<16;i++)b[i]=(byte)(s+i);return b;}static byte[] Key(){var b=new byte[32];for(var i=0;i<32;i++)b[i]=(byte)i;return b;}
 public static int Main(){var random=new Random(7341);var fk=new PhantomForwardKinematics();var ik=new PhantomInverseKinematics(1,.001);for(var i=0;i<10000;i++){var q=new JointAngles(-2.5+5*random.NextDouble(),-1+2*random.NextDouble(),.05+2.7*random.NextDouble());var p=fk.Solve(q,.21,.22);if(Math.Sqrt(p.X*p.X+p.Y*p.Y)<.001)continue;var solved=ik.Solve(p,.21,.22);Check(solved.Success&&(solved.SolvedTarget-p).Magnitude<1e-9,"IK/FK");}
  var mapper=new HumanToRobotMapper(.35);var input=new Vec3(.6,.1,.2);Check(mapper.TryMapVector(input,.65,out var first),"mapping");for(var i=0;i<100000;i++)Check(mapper.TryMapVector(input,.65,out _),"mapping");Check(mapper.TryMapVector(input,.65,out var last)&&(last-first).Magnitude<1e-12,"mapping drift");
  var payload=ProtocolCodec.EncodeCommand(new CommandPayload{Flags=MotionFlags.MotionEnable|MotionFlags.TrackingValid,Target=new JointAngles(1,-2,.5),GripIntent=.25f});var packet=ProtocolCodec.Encode(WireV1.MessageType.Command,payload,Key(),Id(16),Id(32),1,99);Check(ProtocolCodec.TryDecode(packet,Key(),out var decoded)&&ProtocolCodec.TryDecodeCommand(decoded.Payload,out _),"HMAC protocol");packet[70]^=1;Check(!ProtocolCodec.TryDecode(packet,Key(),out _),"HMAC corruption");
  var cal=new ArmReachCalibration();for(var p=0;p<3;p++)for(var i=0;i<30;i++)cal.Add(p,Vec3.Zero,new Vec3(.6+(i%3-1)*.001,0,0));Check(cal.Finish().Valid,"arm reach");var sm=new PhantomStateMachine();var ready=new SafetyPredicates{AppFocused=true,XrReady=true,WristValid=true,ShoulderValid=true,LeftControllerValid=true,UserCalibrationValid=true,NetworkDiscovered=true,Connected=true,RobotReferenceValid=true};Check(sm.Update(ready)==PhantomState.Ready,"ready");Check(sm.Update(ready)==PhantomState.Hold,"hold");ready.EnableHeld=true;Check(sm.Update(ready)==PhantomState.Tracking,"tracking");ready.WristValid=false;Check(sm.Update(ready)==PhantomState.SafeHold,"safe hold");Console.WriteLine("PASS: IK/FK, pure mapping, HMAC wire v1, three-pose calibration, re-arm latch");return 0;}
}
